import { randomUUID } from "node:crypto";
import { and, asc, eq, gt } from "drizzle-orm";
import { Hono } from "hono";
import { z } from "zod";
import { db } from "../db/client.ts";
import { notes } from "../db/schema.ts";
import { requireRole, type AppEnv } from "../lib/auth.ts";
import { cursorQuery, decodeCursor, page, paginate } from "../lib/cursor.ts";
import { idempotency } from "../lib/idempotency.ts";
import { ProblemError, problem } from "../lib/problem.ts";
import { respond, validate } from "../lib/validate.ts";

const Note = z.object({ id: z.string(), title: z.string(), body: z.string().nullable() });
const NoteCreate = z.object({ title: z.string().min(1).max(200), body: z.string().optional() });
const Params = z.object({ id: z.string().min(1) });
const toNote = (r: Pick<typeof notes.$inferSelect, "id" | "title" | "body">): z.infer<typeof Note> => ({
  id: r.id,
  title: r.title,
  body: r.body,
});

export const notesRouter = new Hono<AppEnv>();

notesRouter.get("/", validate("query", cursorQuery), (c) => {
  const { cursor, limit } = c.req.valid("query");
  const after = decodeCursor(cursor);
  const rows = db
    .select({ id: notes.id, title: notes.title, body: notes.body })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), after ? gt(notes.id, after) : undefined))
    .orderBy(asc(notes.id))
    .limit(limit + 1)
    .all();
  const result = paginate(rows, limit);
  return respond(c, page(Note), { data: result.data.map(toNote), next_cursor: result.next_cursor });
});

notesRouter.post("/", requireRole("owner", "member"), idempotency(), validate("json", NoteCreate), (c) => {
  const { title, body } = c.req.valid("json");
  const existing = db
    .select({ id: notes.id })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.title, title)))
    .get();
  if (existing) throw new ProblemError(409, "Conflict", "note title already exists");
  const row = db
    .insert(notes)
    .values({ id: randomUUID(), workspaceId: c.get("user").workspaceId, title, body: body ?? null })
    .returning({ id: notes.id, title: notes.title, body: notes.body })
    .get();
  return respond(c, Note, toNote(row), 201);
});

notesRouter.get("/:id", validate("param", Params), (c) => {
  const { id } = c.req.valid("param");
  const row = db
    .select({ id: notes.id, title: notes.title, body: notes.body })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.id, id)))
    .get();
  if (!row) return problem(c, 404, "Not Found", "note not found");
  return respond(c, Note, toNote(row));
});

notesRouter.delete("/:id", requireRole("owner"), validate("param", Params), (c) => {
  const { id } = c.req.valid("param");
  const row = db
    .delete(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.id, id)))
    .returning({ id: notes.id })
    .get();
  if (!row) return problem(c, 404, "Not Found", "note not found");
  return new Response(null, { status: 204 });
});

import { describe, expect, it } from "vitest";
import { as } from "./helpers.ts";

type Note = { id: string; title: string; body: string | null };
type Page = { data: Note[]; next_cursor: string | null };

describe("/v1/notes", () => {
  it("creates, lists, gets, and deletes notes scoped to workspace", async () => {
    const member = as("notes1", "member");
    const created = (await (await member("POST", "/v1/notes", { title: "a", body: "body" })).json()) as Note;
    expect(created).toMatchObject({ title: "a", body: "body" });

    const list = (await (await as("notes1", "viewer")("GET", "/v1/notes?limit=1")).json()) as Page;
    expect(list.data).toEqual([created]);
    expect(((await (await as("notes2", "viewer")("GET", "/v1/notes")).json()) as Page).data).toEqual([]);

    expect(await (await as("notes1", "viewer")("GET", `/v1/notes/${created.id}`)).json()).toEqual(created);
    expect((await as("notes1", "owner")("DELETE", `/v1/notes/${created.id}`)).status).toBe(204);
    expect((await as("notes1", "viewer")("GET", `/v1/notes/${created.id}`)).status).toBe(404);
  });

  it("enforces duplicate titles and roles", async () => {
    expect((await as("notes3", "viewer")("POST", "/v1/notes", { title: "x" })).status).toBe(403);
    const member = as("notes3", "member");
    expect((await member("POST", "/v1/notes", { title: "x" })).status).toBe(201);
    const duplicate = await member("POST", "/v1/notes", { title: "x" });
    expect(duplicate.status).toBe(409);
    expect(duplicate.headers.get("Content-Type")).toBe("application/problem+json");
    const note = (await (await member("POST", "/v1/notes", { title: "y" })).json()) as Note;
    expect((await as("notes3", "member")("DELETE", `/v1/notes/${note.id}`)).status).toBe(403);
  });
});

