import { Hono } from "hono";
import { z } from "zod";
import { and, desc, eq, lt } from "drizzle-orm";
import { randomUUID } from "node:crypto";

import { db } from "../db/client";
import { notes } from "../db/schema";
import type { AppEnv } from "../lib/auth";
import { requireRole } from "../lib/auth";
import { cursorQuery, decodeCursor, page, paginate } from "../lib/cursor";
import { ProblemError } from "../lib/problem";
import { validate, respond } from "../lib/validate";

const noteSchema = z.object({
  id: z.string(),
  workspaceId: z.string(),
  title: z.string(),
  body: z.string().nullable(),
  createdAt: z.string(),
});

const noteCreate = z.object({
  title: z.string().min(1).max(200),
  body: z.string().optional(),
});

const noteParams = z.object({
  id: z.string().min(1),
});

const noteListQuery = cursorQuery;

const notePage = page(noteSchema);

export const notesRoute = new Hono<AppEnv>();

notesRoute.get("/", validate("query", noteListQuery), async (c) => {
  const user = c.get("user");
  const query = c.req.valid("query");
  const after = decodeCursor(query.cursor);
  const limit = query.limit;

  const rows = await db
    .select({
      id: notes.id,
      workspaceId: notes.workspaceId,
      title: notes.title,
      body: notes.body,
      createdAt: notes.createdAt,
    })
    .from(notes)
    .where(
      after
        ? and(eq(notes.workspaceId, user.workspaceId), lt(notes.id, after))
        : eq(notes.workspaceId, user.workspaceId),
    )
    .orderBy(desc(notes.id))
    .limit(limit + 1);

  return respond(c, notePage, paginate(rows, limit));
});

notesRoute.post("/", requireRole("owner", "member"), validate("json", noteCreate), async (c) => {
  const user = c.get("user");
  const body = c.req.valid("json");
  const existing = await db
    .select({ id: notes.id })
    .from(notes)
    .where(and(eq(notes.workspaceId, user.workspaceId), eq(notes.title, body.title)))
    .limit(1);

  if (existing.length > 0) {
    throw new ProblemError(409, "Conflict", "A note with this title already exists");
  }

  const now = new Date().toISOString();
  const row = {
    id: randomUUID(),
    workspaceId: user.workspaceId,
    title: body.title,
    body: body.body ?? null,
    createdAt: now,
  };

  await db.insert(notes).values(row);

  return respond(c, noteSchema, row, 201);
});

notesRoute.get("/:id", validate("param", noteParams), async (c) => {
  const user = c.get("user");
  const params = c.req.valid("param");
  const rows = await db
    .select({
      id: notes.id,
      workspaceId: notes.workspaceId,
      title: notes.title,
      body: notes.body,
      createdAt: notes.createdAt,
    })
    .from(notes)
    .where(and(eq(notes.workspaceId, user.workspaceId), eq(notes.id, params.id)))
    .limit(1);

  const row = rows[0];
  if (!row) {
    throw new ProblemError(404, "Not Found", "Note not found");
  }

  return respond(c, noteSchema, row);
});

notesRoute.delete("/:id", requireRole("owner"), validate("param", noteParams), async (c) => {
  const user = c.get("user");
  const params = c.req.valid("param");
  const rows = await db
    .select({ id: notes.id })
    .from(notes)
    .where(and(eq(notes.workspaceId, user.workspaceId), eq(notes.id, params.id)))
    .limit(1);

  if (!rows[0]) {
    throw new ProblemError(404, "Not Found", "Note not found");
  }

  await db.delete(notes).where(and(eq(notes.workspaceId, user.workspaceId), eq(notes.id, params.id)));

  return c.body(null, 204);
});

