export const notes = sqliteTable(
  "notes",
  {
    id: text("id").primaryKey(),
    workspaceId: text("workspace_id").notNull(),
    title: text("title").notNull(),
    body: text("body"),
    createdAt: text("created_at").notNull(),
  },
  (table) => ({
    notesWorkspaceTitleUnique: uniqueIndex("notes_workspace_title_unique").on(table.workspaceId, table.title),
  }),
);

// CREATE TABLE statements matching schema.ts, run in order at startup.
export const migrations: string[] = [
  `CREATE TABLE IF NOT EXISTS examples (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, name TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS notes (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT, created_at TEXT NOT NULL)`,
  `CREATE UNIQUE INDEX IF NOT EXISTS notes_workspace_title_unique ON notes (workspace_id, title)`,
];

